:root { font-family: system-ui, sans-serif; color: #203047; background: #f4f6fa; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #dce2eb; border-radius: 12px; }
h1 { margin-top: 0; }
h2 { margin-top: 32px; font-size: 1.2rem; }
label { display: block; margin-bottom: 8px; font-weight: 600; }
.form-controls { display: flex; gap: 12px; }
input { flex: 1; min-width: 0; padding: 10px; border: 1px solid #8997ab; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 1px solid #254db5; border-radius: 6px; background: #254db5; color: white; font: inherit; cursor: pointer; }
button:hover { background: #183b96; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #d98b00; outline-offset: 3px; }
.project-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 0; border-bottom: 1px solid #dce2eb; }
.project-row span { overflow-wrap: anywhere; }
.project-row button { flex-shrink: 0; }
