import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

const databasePath = process.env.DB_PATH || './data/workboard.sqlite';
if (databasePath !== ':memory:') mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec('PRAGMA foreign_keys = ON');
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  );
  CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id);
`);
// Existing databases predate archive support; preserve their projects and tasks.
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
const projectSelect = `SELECT p.id, p.name, p.archived,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id) AS total,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1) AS completed
  FROM projects p`;
const listProjects = database.prepare(`${projectSelect} ORDER BY p.id`);
const findProject = database.prepare(`${projectSelect} WHERE p.id = ?`);
const updateProject = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const projectJson = (project) => ({ ...project, archived: Boolean(project.archived) });
const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const findTask = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const taskJson = (task) => ({ ...task, completed: Boolean(task.completed) });
const assets = new Map([
  ['/', ['public/index.html', 'text/html; charset=utf-8']],
  ['/app.js', ['public/app.js', 'text/javascript; charset=utf-8']],
  ['/styles.css', ['public/styles.css', 'text/css; charset=utf-8']],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  const chunks = [];
  let bytes = 0;
  for await (const chunk of request) {
    bytes += chunk.length;
    if (bytes > 65536) throw Object.assign(new Error('Request is too large'), { status: 413 });
    chunks.push(chunk);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString('utf8'));
  } catch {
    throw Object.assign(new Error('Invalid JSON'), { status: 400 });
  }
}

const server = http.createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (path === '/api/projects' && request.method === 'GET') {
      return json(response, 200, listProjects.all().map(projectJson));
    }
    if (path === '/api/projects' && request.method === 'POST') {
      const body = await readJson(request);
      const name = typeof body?.name === 'string' ? body.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(response, 201, projectJson(findProject.get(Number(result.lastInsertRowid))));
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const projectId = Number(tasksMatch[1]);
      const taskId = tasksMatch[2] ? Number(tasksMatch[2]) : null;
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (project.archived && ['POST', 'PATCH'].includes(request.method)) {
        return json(response, 409, { error: 'Archived project is read-only' });
      }
      if (taskId === null && request.method === 'GET') {
        return json(response, 200, listTasks.all(projectId).map(taskJson));
      }
      if (taskId === null && request.method === 'POST') {
        const body = await readJson(request);
        const title = typeof body?.title === 'string' ? body.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const result = insertTask.run(projectId, title);
        return json(response, 201, taskJson(findTask.get(projectId, Number(result.lastInsertRowid))));
      }
      if (taskId !== null && request.method === 'PATCH') {
        if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const body = await readJson(request);
        if (typeof body?.completed !== 'boolean') {
          return json(response, 400, { error: 'Completed must be a boolean' });
        }
        updateTask.run(Number(body.completed), projectId, taskId);
        return json(response, 200, taskJson(findTask.get(projectId, taskId)));
      }
    }
    const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (projectMatch && ['GET', 'PATCH'].includes(request.method)) {
      const projectId = Number(projectMatch[1]);
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (request.method === 'PATCH') {
        const body = await readJson(request);
        if (body && Object.hasOwn(body, 'name')) {
          if (Object.hasOwn(body, 'archived')) {
            return json(response, 400, { error: 'Rename and archive must be separate requests' });
          }
          if (project.archived) {
            return json(response, 409, { error: 'Archived project is read-only' });
          }
          const name = typeof body.name === 'string' ? body.name.trim() : '';
          if (!name) return json(response, 400, { error: 'Project name is required' });
          renameProject.run(name, projectId);
        } else {
          if (typeof body?.archived !== 'boolean') {
            return json(response, 400, { error: 'Archived must be a boolean' });
          }
          updateProject.run(Number(body.archived), projectId);
        }
      }
      return json(response, 200, projectJson(findProject.get(projectId)));
    }
    const asset = /^\/projects\/\d+$/.test(path) ? assets.get('/') : assets.get(path);
    if (request.method === 'GET' && asset) {
      const content = await readFile(new URL(asset[0], import.meta.url));
      response.writeHead(200, { 'Content-Type': asset[1] });
      return response.end(content);
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    json(response, error.status || 500, { error: error.status ? error.message : 'Internal server error' });
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    database.close();
    process.exit(0);
  }));
}

{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}

const heading = document.querySelector('#heading');
const alert = document.querySelector('#alert');
const form = document.querySelector('#create-project');
const nameInput = document.querySelector('#project-name');
const projects = document.querySelector('#projects');
const projectFilter = document.querySelector('#project-filter');
let projectItems = [];
let archived = false;
const renameForm = document.querySelector('#rename-project');
const newNameInput = document.querySelector('#new-project-name');
const taskForm = document.querySelector('#create-task');
const titleInput = document.querySelector('#task-title');
const taskFilter = document.querySelector('#task-filter');
const tasksElement = document.querySelector('#tasks');
const projectId = window.location.pathname.match(/^\/projects\/(\d+)$/)?.[1];
let tasks = [];

function showError(message) {
  alert.textContent = message;
  alert.hidden = false;
}

async function api(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Unable to complete request');
  return body;
}

function addProject(project) {
  const row = document.createElement('div');
  row.className = 'project-row';
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const open = document.createElement('button');
  open.type = 'button';
  open.textContent = 'Open project';
  open.addEventListener('click', () => {
    window.location.href = `/projects/${project.id}`;
  });
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completed}/${project.total} completed`;
  const archive = document.createElement('button');
  archive.type = 'button';
  archive.textContent = project.archived ? 'Restore project' : 'Archive project';
  archive.addEventListener('click', async () => {
    alert.hidden = true;
    archive.disabled = true;
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, saved);
      renderProjects();
    } catch (error) {
      showError(error.message);
      archive.disabled = false;
    }
  });
  row.append(name, summary, open, archive);
  projects.append(row);
}

function renderProjects() {
  projects.replaceChildren();
  const items = projectItems.filter((project) => project.archived === (projectFilter.value === 'Archived'));
  items.forEach(addProject);
  document.querySelector('#empty').hidden = items.length !== 0;
}

projectFilter.addEventListener('change', renderProjects);

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  alert.hidden = true;
  if (!nameInput.value.trim()) {
    showError('Project name is required');
    return;
  }
  const submit = form.querySelector('button');
  submit.disabled = true;
  try {
    const project = await api('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: nameInput.value }),
    });
    projectItems.push(project);
    renderProjects();
    nameInput.value = '';
    nameInput.focus();
  } catch (error) {
    showError(error.message);
  } finally {
    submit.disabled = false;
  }
});

function renderTasks() {
  tasksElement.replaceChildren();
  for (const task of tasks) {
    if (taskFilter.value === 'Open' && task.completed) continue;
    if (taskFilter.value === 'Completed' && !task.completed) continue;
    const row = document.createElement('div');
    row.className = 'task-row';
    row.dataset.testid = 'task-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.disabled = archived;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      alert.hidden = true;
      checkbox.disabled = true;
      try {
        const saved = await api(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        Object.assign(task, saved);
        renderTasks();
      } catch (error) {
        checkbox.checked = task.completed;
        showError(error.message);
      } finally {
        checkbox.disabled = archived;
      }
    });
    row.append(title, checkbox);
    tasksElement.append(row);
  }
}

taskFilter.addEventListener('change', renderTasks);
taskForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  alert.hidden = true;
  if (archived) return;
  if (!titleInput.value.trim()) {
    showError('Task title is required');
    return;
  }
  const submit = taskForm.querySelector('button');
  submit.disabled = true;
  try {
    const task = await api(`/api/projects/${projectId}/tasks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title: titleInput.value }),
    });
    tasks.push(task);
    renderTasks();
    titleInput.value = '';
    titleInput.focus();
  } catch (error) {
    showError(error.message);
  } finally {
    submit.disabled = archived;
  }
});

function setProjectName(name) {
  heading.textContent = name;
  document.title = `${name} · Workboard`;
}

renameForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  alert.hidden = true;
  if (archived) return;
  if (!newNameInput.value.trim()) {
    showError('Project name is required');
    return;
  }
  const submit = renameForm.querySelector('button');
  submit.disabled = true;
  try {
    const project = await api(`/api/projects/${projectId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: newNameInput.value }),
    });
    setProjectName(project.name);
    newNameInput.value = '';
    newNameInput.focus();
  } catch (error) {
    showError(error.message);
  } finally {
    submit.disabled = archived;
  }
});

document.querySelector('#back').addEventListener('click', () => {
  window.location.href = '/';
});

async function loadPage() {
  const match = window.location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    document.querySelector('#project-detail').hidden = false;
    const project = await api(`/api/projects/${match[1]}`);
    archived = project.archived;
    document.querySelector('#archived-notice').hidden = !archived;
    taskForm.querySelector('button').disabled = archived;
    titleInput.disabled = archived;
    renameForm.querySelector('button').disabled = archived;
    newNameInput.disabled = archived;
    setProjectName(project.name);
    tasks = await api(`/api/projects/${project.id}/tasks`);
    renderTasks();
  } else {
    document.querySelector('#project-list').hidden = false;
    projectItems = await api('/api/projects');
    renderProjects();
  }
}

loadPage().catch((error) => showError(error.message));

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from 'node:net';
import { DatabaseSync } from 'node:sqlite';

async function freePort() {
  const server = createServer();
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  const port = server.address().port;
  await new Promise((resolve) => server.close(resolve));
  return port;
}

test('project and task validation, isolation, order, and persistence across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const port = await freePort();
  const base = `http://127.0.0.1:${port}`;
  let child;
  let errors = '';
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'nested', 'projects.sqlite') },
      stdio: ['ignore', 'ignore', 'pipe'],
    });
    child.stderr.on('data', (data) => { errors += data; });
    for (let attempt = 0; attempt < 100; attempt++) {
      if (child.exitCode !== null) throw new Error(errors);
      try {
        const response = await fetch(`${base}/health`);
        assert.equal(response.status, 200);
        assert.deepEqual(await response.json(), { status: 'ok' });
        return;
      } catch {
        await new Promise((resolve) => setTimeout(resolve, 25));
      }
    }
    throw new Error(`Server did not start: ${errors}`);
  }
  async function stop() {
    if (child && child.exitCode === null) {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    }
  }
  async function create(name) {
    return fetch(`${base}/api/projects`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
    });
  }
  try {
    await start();
    for (const name of ['', ' \n\t ', null, 12]) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
    }
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), []);
    const firstResponse = await create('  Alpha 🐱  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'Alpha 🐱');
    assert.equal(first.archived, false);
    assert.equal(first.total, 0);
    assert.equal(first.completed, 0);
    const second = await (await create('<script>Second</script>')).json();
    const expected = [first, second];
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), expected);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    for (const path of ['/', `/projects/${first.id}`]) {
      const response = await fetch(`${base}${path}`);
      assert.equal(response.status, 200);
      assert.match(await response.text(), /<title>Workboard<\/title>/);
    }
    assert.equal((await fetch(`${base}/api/projects/99999`)).status, 404);
    const invalidJson = await fetch(`${base}/api/projects`, { method: 'POST', body: '{' });
    assert.equal(invalidJson.status, 400);
    const taskPath = `/api/projects/${first.id}/tasks`;
    async function taskRequest(path, method, body) {
      return fetch(`${base}${path}`, {
        method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
      });
    }
    for (const title of ['', ' \n\t ', null, 12]) {
      const response = await taskRequest(taskPath, 'POST', { title });
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Task title is required' });
    }
    assert.deepEqual(await (await fetch(`${base}${taskPath}`)).json(), []);
    const taskResponse = await taskRequest(taskPath, 'POST', { title: '  First task 🐱  ' });
    assert.equal(taskResponse.status, 201);
    const task = await taskResponse.json();
    assert.equal(task.title, 'First task 🐱');
    assert.equal(task.completed, false);
    const nextTask = await (await taskRequest(taskPath, 'POST', { title: 'Second task' })).json();
    assert.deepEqual(await (await fetch(`${base}${taskPath}`)).json(), [task, nextTask]);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${second.id}/tasks`)).json(), []);
    assert.equal((await taskRequest(`/api/projects/${second.id}/tasks/${task.id}`, 'PATCH', { completed: true })).status, 404);
    assert.equal((await taskRequest('/api/projects/99999/tasks', 'POST', { title: 'Orphan' })).status, 404);
    assert.equal((await taskRequest(`${taskPath}/${task.id}`, 'PATCH', { completed: 'true' })).status, 400);
    for (const completed of [true, false, true]) {
      const response = await taskRequest(`${taskPath}/${task.id}`, 'PATCH', { completed });
      assert.equal(response.status, 200);
      assert.deepEqual(await response.json(), { ...task, completed });
    }
    const savedTasks = [{ ...task, completed: true }, nextTask];
    Object.assign(first, { total: 2, completed: 1 });
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), expected);
    const projectPath = `/api/projects/${first.id}`;
    for (const name of ['', ' \n\t ', null, 12]) {
      const response = await taskRequest(projectPath, 'PATCH', { name });
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
      assert.deepEqual(await (await fetch(`${base}${projectPath}`)).json(), first);
    }
    assert.equal((await taskRequest(projectPath, 'PATCH', { name: 'Invalid combined update', archived: true })).status, 400);
    assert.equal((await taskRequest('/api/projects/99999', 'PATCH', { name: 'Missing' })).status, 404);
    const renameResponse = await taskRequest(projectPath, 'PATCH', { name: '  Renamed 🐱  ' });
    assert.equal(renameResponse.status, 200);
    first.name = 'Renamed 🐱';
    assert.deepEqual(await renameResponse.json(), first);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), expected);
    assert.deepEqual(await (await fetch(`${base}${taskPath}`)).json(), savedTasks);
    assert.equal((await taskRequest(`/api/projects/${first.id}`, 'PATCH', { archived: 'true' })).status, 400);
    assert.equal((await taskRequest('/api/projects/99999', 'PATCH', { archived: true })).status, 404);
    const archiveResponse = await taskRequest(`/api/projects/${first.id}`, 'PATCH', { archived: true });
    assert.equal(archiveResponse.status, 200);
    first.archived = true;
    assert.deepEqual(await archiveResponse.json(), first);
    assert.equal((await taskRequest(projectPath, 'PATCH', { name: 'Blocked rename' })).status, 409);
    assert.deepEqual(await (await fetch(`${base}${projectPath}`)).json(), first);
    assert.equal((await taskRequest(taskPath, 'POST', { title: 'Blocked' })).status, 409);
    assert.equal((await taskRequest(`${taskPath}/${task.id}`, 'PATCH', { completed: false })).status, 409);
    assert.deepEqual(await (await fetch(`${base}${taskPath}`)).json(), savedTasks);
    await stop();
    await start();
    assert.deepEqual(await (await fetch(`${base}${taskPath}`)).json(), savedTasks);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${second.id}/tasks`)).json(), []);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), expected);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    const restoreResponse = await taskRequest(`/api/projects/${first.id}`, 'PATCH', { archived: false });
    assert.equal(restoreResponse.status, 200);
    first.archived = false;
    assert.deepEqual(await restoreResponse.json(), first);
    const restoredRename = await taskRequest(projectPath, 'PATCH', { name: '  Restored name  ' });
    assert.equal(restoredRename.status, 200);
    first.name = 'Restored name';
    assert.deepEqual(await restoredRename.json(), first);
    assert.deepEqual(await (await fetch(`${base}${taskPath}`)).json(), savedTasks);
    await stop();
    await start();
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), expected);
    assert.equal((await taskRequest(`${taskPath}/${task.id}`, 'PATCH', { completed: false })).status, 200);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), { ...first, completed: 0 });
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('upgrades a pre-archive database without losing existing data', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-migration-'));
  const databasePath = join(directory, 'legacy.sqlite');
  const database = new DatabaseSync(databasePath);
  database.exec(`
    CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
    CREATE TABLE tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL,
      completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
    );
    INSERT INTO projects (id, name) VALUES (7, 'Existing project');
    INSERT INTO tasks (id, project_id, title, completed) VALUES (9, 7, 'Existing task', 1);
  `);
  database.close();
  const port = await freePort();
  const base = `http://127.0.0.1:${port}`;
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: String(port), DB_PATH: databasePath },
    stdio: ['ignore', 'ignore', 'pipe'],
  });
  let errors = '';
  child.stderr.on('data', (data) => { errors += data; });
  try {
    let ready = false;
    for (let attempt = 0; attempt < 100; attempt++) {
      if (child.exitCode !== null) throw new Error(errors);
      try {
        ready = (await fetch(`${base}/health`)).ok;
        if (ready) break;
      } catch { /* Wait for the server to bind. */ }
      await new Promise((resolve) => setTimeout(resolve, 25));
    }
    assert.ok(ready, errors);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [
      { id: 7, name: 'Existing project', archived: false, total: 1, completed: 1 },
    ]);
    assert.deepEqual(await (await fetch(`${base}/api/projects/7/tasks`)).json(), [
      { id: 9, title: 'Existing task', completed: true },
    ]);
  } finally {
    if (child.exitCode === null) {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    }
    await rm(directory, { recursive: true, force: true });
  }
});

